def _decode(token):
    # RFC 6901: '~1' means '/', '~0' means '~', decoded in that order.
    return token.replace('~1', '/').replace('~0', '~')


def _tokens(pointer):
    if not isinstance(pointer, str) or not pointer.startswith('/'):
        raise KeyError(pointer)
    return [_decode(t) for t in pointer[1:].split('/')]


def _index(token):
    # A list index is a non-empty run of ASCII decimal digits.
    if token and all('0' <= c <= '9' for c in token):
        return int(token)
    return None


def _step(node, token):
    if isinstance(node, dict):
        if token not in node:
            raise KeyError(token)
        return node[token]
    if isinstance(node, list):
        i = _index(token)
        if i is None or i >= len(node):
            raise KeyError(token)
        return node[i]
    raise KeyError(token)  # step into a scalar


def resolve(doc, pointer):
    if pointer == '':
        return doc
    node = doc
    for token in _tokens(pointer):
        node = _step(node, token)
    return node


def set_at(doc, pointer, value):
    tokens = _tokens(pointer)
    node = doc
    for token in tokens[:-1]:
        node = _step(node, token)
    last = tokens[-1]
    if isinstance(node, dict):
        node[last] = value
    elif isinstance(node, list):
        if last == '-':
            node.append(value)
        else:
            i = _index(last)
            if i is None or i >= len(node):
                raise KeyError(last)
            node[i] = value
    else:
        raise KeyError(last)

